import { useRef, useState } from 'react'
import CodeEditor from './CodeEditor'
import FileTree from './FileTree'
import { useCodeViewStore, codeViewStore } from './CodeViewStore'
import { useProjectGroupFileMap } from './useProjectGroupFileMap'
import { createNativeStackNavigator } from '@react-navigation/native-stack'
import {
	NavigationContainer,
	NavigationIndependentTree,
	useNavigation
} from '@react-navigation/native'
import type { NativeStackNavigationProp } from '@react-navigation/native-stack'
import { CloseIcon } from '../launcher-menu/components'
import { ChevronLeft } from 'lucide-react-native'
import { colors } from '@/theme'
import { ActivityIndicator, Pressable, Text, View } from 'react-native'
import { LiquidGlassView } from '@/components'
import {
	ProjectRevisionAction,
	useCreateNewFileMutation,
	useCreateProjectRevisionMutation
} from '@/generated/graphql'
import { StatusBar } from 'expo-status-bar'

const theme = 'dark'

interface FileTreeRef {
	scrollToFile: (filePath: string) => void
}

type RootStackParamList = {
	FileTree: undefined
	CodeEditor: undefined
}

const Stack = createNativeStackNavigator<RootStackParamList>()

const FileTreeContainer = () => {
	const navigation =
		useNavigation<NativeStackNavigationProp<RootStackParamList>>()

	const fileTreeScrollRef = useRef<FileTreeRef>(null)
	const filePath = useCodeViewStore((state) => state.filePath)
	const setFilePath = useCodeViewStore((state) => state.setFilePath)
	const expandedFolders = useCodeViewStore((state) => state.expandedFolders)
	const setExpandedFolders = useCodeViewStore(
		(state) => state.setExpandedFolders
	)
	const { fs } = useProjectGroupFileMap()

	return (
		<FileTree
			fs={fs}
			ref={fileTreeScrollRef}
			filePath={filePath}
			expandedItems={expandedFolders.filter(
				(item): item is string => typeof item === 'string'
			)}
			onExpandedItemsChange={(items) => setExpandedFolders(items)}
			onSelect={(selectedFilePath) => {
				setFilePath(selectedFilePath)
				navigation.navigate('CodeEditor')
			}}
		/>
	)
}

const CodeEditorContainer = (onClose: () => void) => () => {
	const filePath = useCodeViewStore((state) => state.filePath)
	const { fs, fileMap } = useProjectGroupFileMap()
	const [code, setCode] = useState<string | null>(
		filePath ? fs[filePath] : null
	)
	const [createProjectRevision, { loading: createProjectRevisionLoading }] =
		useCreateProjectRevisionMutation()
	const [createFile, { loading: createFileLoading }] = useCreateNewFileMutation(
		{}
	)

	const loading = createProjectRevisionLoading || createFileLoading

	if (!code || !filePath) {
		return null
	}

	const isChanged = code !== fs[filePath]

	return (
		<>
			<CodeEditor code={code} onChange={setCode} />
			{isChanged && (
				<Pressable
					disabled={loading}
					style={{
						position: 'absolute',
						bottom: 0,
						left: 0,
						right: 0,
						padding: 16,
						alignItems: 'center'
					}}
					onPress={() => {
						const projectId = fileMap[filePath]
						if (projectId) {
							createProjectRevision({
								variables: {
									projectId,
									content: code,
									action: ProjectRevisionAction.CODE_CHANGE
								}
							}).then(onClose)
						} else {
							createFile({
								variables: {
									input: {
										projectGroupId: process.env.EXPO_PUBLIC_PROJECT_GROUP_ID,
										path: filePath,
										content: code,
										action: ProjectRevisionAction.CODE_CHANGE
									}
								}
							}).then(onClose)
						}
					}}
				>
					<View
						style={{
							position: 'absolute',
							bottom: 0,
							left: 0,
							right: 0,
							padding: 16,
							alignItems: 'center'
						}}
					>
						<Pressable disabled={loading}>
							<LiquidGlassView
								glassEffectStyle="clear"
								style={{
									width: 100,
									padding: 16,
									borderRadius: 16,
									alignItems: 'center',
									justifyContent: 'center'
								}}
								isInteractive
								tintColor={theme}
							>
								{loading ? (
									<ActivityIndicator
										size="small"
										color={colors[theme].gray[900]}
									/>
								) : (
									<Text
										style={{ color: colors[theme].gray[900], fontSize: 16 }}
									>
										Update
									</Text>
								)}
							</LiquidGlassView>
						</Pressable>
					</View>
				</Pressable>
			)}
		</>
	)
}

export const CodeEditorScreen = ({ onClose }: { onClose: () => void }) => {
	return (
		<>
			<StatusBar style="light" />
			<NavigationIndependentTree>
				<NavigationContainer>
					<Stack.Navigator
						screenOptions={{
							headerShown: true,
							animation: 'slide_from_right',
							gestureEnabled: true,
							headerStyle: {
								backgroundColor: colors[theme].gray[25]
							},
							contentStyle: {
								backgroundColor: colors[theme].gray[25]
							}
						}}
					>
						<Stack.Screen
							name="FileTree"
							component={FileTreeContainer}
							options={{
								headerLeft: () => (
									<Pressable onPress={onClose} style={{ marginLeft: 10 }}>
										<CloseIcon color={colors[theme].gray[900]} />
									</Pressable>
								),
								headerTitle: 'Editor',
								headerTitleStyle: {
									color: colors[theme].gray[900]
								}
							}}
						/>
						<Stack.Screen
							name="CodeEditor"
							component={CodeEditorContainer(onClose)}
							options={() => {
								const filePath = codeViewStore.getState().filePath
								return {
									headerTitle:
										filePath?.split('/').slice(-2).join('/') ?? 'Code',
									headerLeft: () => {
										const navigation =
											useNavigation<
												NativeStackNavigationProp<RootStackParamList>
											>()
										return (
											<Pressable
												onPress={() => navigation.goBack()}
												style={{ marginLeft: 6 }}
											>
												<ChevronLeft color={colors[theme].gray[900]} />
											</Pressable>
										)
									},
									headerTitleStyle: {
										color: colors[theme].gray[900]
									},
									cardStyle: {
										backgroundColor: colors[theme].gray[25]
									}
								}
							}}
						/>
					</Stack.Navigator>
				</NavigationContainer>
			</NavigationIndependentTree>
		</>
	)
}
